  return (raw || "").replace(/ ?[-|] ?Reddit$/i, "").replace(/ ?[-|] ?r\/\w+$/i, "").trim();
}

function extractSubreddit(url) {
  var match = (url || "").match(/reddit\.com\/r\/([^\/]+)/i);
  return match ? match[1] : "unknown";
}

for (var i = 0; i < warmupSubreddits.length; i++) {
